def determine_classe(x):
    bin = ""
    while x != 0:
        r = x % 2
        x = x // 2
        bin = str(r) + bin
    if bin[0] == "0":
        return "A"
    elif bin[1] == "0":
        return "B"
    elif bin[2] == "0":
        return "C"
    elif bin[3] == "0":
        return "D"
    else:
        return "E"

